insert into public.site_settings (site_name, logo_dark_media_id, logo_light_media_id, seo_title_en, seo_title_bn, seo_description_en, seo_description_bn, whatsapp_number, whatsapp_message_en, copyright_en, copyright_bn, footer_tagline_en, footer_tagline_bn, primary_cta_url) values
  ('MediVerse Dental', (select id from public.media where path = 'logos/logo-white.png'), (select id from public.media where path = 'logos/logo-blue.png'), 'MediVerse Dental — Future Dentistry Begins Here', 'মেডিভার্স ডেন্টাল — ডেন্টিস্ট্রির ভবিষ্যৎ শুরু এখান থেকেই', 'MediVerse Dental — phase-wise BDS courses, expert mentors and exam-focused notes for dental students across Bangladesh.', 'ফেজ ধরে সাজানো BDS কোর্স, অভিজ্ঞ মেন্টর আর পরীক্ষার নোটস — বাংলাদেশের ডেন্টাল স্টুডেন্টদের জন্য।', '+8801726415926', 'Hello MediVerse Dental, I would like to know more about your BDS courses.', 'MediVerse Dental. All rights reserved.', 'মেডিভার্স ডেন্টাল। সর্বস্বত্ব সংরক্ষিত।', 'Made for BDS students, by expert mentors 🦷', 'BDS স্টুডেন্টদের জন্য, এক্সপার্ট মেন্টরদের হাতে বানানো 🦷', 'https://mediversebd.com');
insert into public.phases (code, name_en, name_bn, summary_en, summary_bn, sort_order) values
  (1, '1st Phase', '১ম ফেজ', 'SDM, Dental Anatomy, Physiology, Biochemistry — the foundation, with diagram-heavy notes and viva prep.', 'SDM, Dental Anatomy, Physiology, Biochemistry — বেসটা এখানেই শক্ত হয়। সাথে ডায়াগ্রামসহ নোটস আর ভাইভা প্রস্তুতি।', 10),
  (2, '2nd Phase', '২য় ফেজ', 'Pharmacology, Pathology, Microbiology — dense subjects distilled into exam-ready summaries.', 'Pharmacology, Pathology, Microbiology — ভারী ভারী সাবজেক্টগুলো ছোট করে, পরীক্ষার উপযোগী করে গুছিয়ে দেওয়া।', 20),
  (3, '3rd Phase', '৩য় ফেজ', 'Oral Pathology & Medicine, Periodontology, Medicine, Surgery — where clinical thinking takes shape.', 'Oral Pathology & Medicine, Periodontology, Medicine, Surgery — এখান থেকেই ক্লিনিক্যালি ভাবতে শেখা শুরু।', 30),
  (4, 'Final Phase', 'ফাইনাল ফেজ', 'OMS, Conservative, Orthodontics, Prosthodontics, Pedodontics — mastery for finals.', 'OMS, Conservative, Orthodontics, Prosthodontics, Pedodontics — ফাইনালের পুরো প্রস্তুতি।', 40);
insert into public.courses (slug, title_en, title_bn, short_desc_en, short_desc_bn, phase_id, flyer_media_id, external_url, cta_label_en, cta_label_bn, search_keywords, status, sort_order) values
  ('sdm-full-course', 'SDM Full Course', null, 'Complete Science of Dental Materials, exam-mapped from the start.', 'পুরো Science of Dental Materials — শুরু থেকেই পরীক্ষার কথা মাথায় রেখে সাজানো।', (select id from public.phases where code = 1), (select id from public.media where path = 'flyers/sdm-full.jpg'), 'https://mediversebd.com/courses/science-of-dental-materials-full-course', 'Enroll on Mediverse', 'মেডিভার্সে এনরোল করো', array['science', 'of', 'dental', 'materials']::text[], 'active', 10),
  ('sdm-crash-course', 'SDM Crash Course', null, 'A fast, exam-focused refresher covering SDM''s high-yield topics.', 'SDM-এর ইম্পর্ট্যান্ট টপিকগুলোর ঝটপট রিভিশন — পরীক্ষার ঠিক আগে কাজে লাগবে।', (select id from public.phases where code = 1), (select id from public.media where path = 'flyers/sdm-crash.jpg'), 'https://mediversebd.com/courses/sdm-crash-course', 'Enroll on Mediverse', 'মেডিভার্সে এনরোল করো', array['science', 'of', 'dental', 'materials', 'revision']::text[], 'active', 20),
  ('dental-anatomy-full-course', 'Dental Anatomy Full Course', null, 'Tooth morphology through full arch relations and occlusion.', 'দাঁতের মরফোলজি থেকে শুরু করে ফুল আর্চ রিলেশন আর অক্লুশন পর্যন্ত।', (select id from public.phases where code = 1), (select id from public.media where path = 'flyers/dental-anatomy.jpg'), 'https://mediversebd.com/courses/dental-anatomy-full-course', 'Enroll on Mediverse', 'মেডিভার্সে এনরোল করো', array['da', 'tooth', 'morphology']::text[], 'active', 30),
  ('anatomy-1st-term', 'Anatomy 1st Term', null, 'Foundational general anatomy, structured for early BDS.', 'BDS-এর শুরুতে জেনারেল অ্যানাটমির বেসটা শক্ত করার কোর্স।', (select id from public.phases where code = 1), (select id from public.media where path = 'flyers/anatomy-1.jpg'), 'https://mediversebd.com/courses/anatomy-first-term-for-bds', 'Enroll on Mediverse', 'মেডিভার্সে এনরোল করো', array['general', 'anatomy']::text[], 'active', 40),
  ('anatomy-2nd-term', 'Anatomy 2nd Term', null, 'Continues core anatomy with viva-focused revision notes.', 'অ্যানাটমির বাকি অংশ, সাথে ভাইভার জন্য রিভিশন নোটস।', (select id from public.phases where code = 1), (select id from public.media where path = 'flyers/anatomy-2.jpg'), 'https://mediversebd.com/courses/anatomy-second-term-for-bds', 'Enroll on Mediverse', 'মেডিভার্সে এনরোল করো', array['general', 'anatomy']::text[], 'active', 50),
  ('dental-morphology', 'Dental Morphology', null, 'Tooth form and function, mapped for practical and theory exams.', 'দাঁতের গঠন আর কাজ — প্র্যাকটিক্যাল আর থিওরি, দুই পরীক্ষার জন্যই।', (select id from public.phases where code = 1), (select id from public.media where path = 'flyers/dental-morphology.jpg'), 'https://mediversebd.com/courses/dental-morphology', 'Enroll on Mediverse', 'মেডিভার্সে এনরোল করো', array['tooth', 'anatomy']::text[], 'active', 60),
  ('essential-physiology', 'Essential Physiology', null, 'Systems-based physiology notes built for BDS first phase.', 'সিস্টেম ধরে ধরে ফিজিওলজি নোটস, BDS ফার্স্ট ফেজের জন্য বানানো।', (select id from public.phases where code = 1), (select id from public.media where path = 'flyers/physiology.jpg'), 'https://mediversebd.com/courses/essential-physiology-for-bds', 'Enroll on Mediverse', 'মেডিভার্সে এনরোল করো', '{}'::text[], 'active', 70),
  ('essential-biochemistry', 'Essential Biochemistry', null, 'Core biochemical concepts, simplified for dental students.', 'বায়োকেমিস্ট্রির মূল কনসেপ্টগুলো, ডেন্টাল স্টুডেন্টদের জন্য সহজ করে।', (select id from public.phases where code = 1), (select id from public.media where path = 'flyers/biochemistry.jpg'), 'https://mediversebd.com/courses/essential-biochemistry-for-bds', 'Enroll on Mediverse', 'মেডিভার্সে এনরোল করো', '{}'::text[], 'active', 80),
  ('dental-pharmacology', 'Dental Pharmacology', null, 'Drug classes and dental prescriptions, exam-focused.', 'ড্রাগের ক্লাস আর ডেন্টাল প্রেসক্রিপশন — পরীক্ষায় যেভাবে আসে, সেভাবেই।', (select id from public.phases where code = 2), (select id from public.media where path = 'flyers/dental-pharmacology.jpg'), 'https://mediversebd.com/courses/dental-pharmacology', 'Enroll on Mediverse', 'মেডিভার্সে এনরোল করো', array['drugs', 'prescription']::text[], 'active', 90),
  ('essential-pathology-for-bds', 'Essential Pathology for BDS', null, 'Concept-first notes on inflammation, neoplasia and healing.', 'ইনফ্লামেশন, নিওপ্লাসিয়া, হিলিং — আগে কনসেপ্ট পরিষ্কার, তারপর নোটস।', (select id from public.phases where code = 2), (select id from public.media where path = 'flyers/pathology.jpg'), 'https://mediversebd.com/courses/essential-pathology-for-bds', 'Enroll on Mediverse', 'মেডিভার্সে এনরোল করো', array['general', 'pathology']::text[], 'active', 100),
  ('microbiology', 'Microbiology', null, 'Organism-wise notes built around board-relevant clinical links.', 'অর্গানিজম ধরে ধরে নোটস, সাথে পরীক্ষায় আসা ক্লিনিক্যাল কানেকশন।', (select id from public.phases where code = 2), (select id from public.media where path = 'flyers/microbiology.jpg'), 'https://mediversebd.com/courses/microbiology-full-course', 'Enroll on Mediverse', 'মেডিভার্সে এনরোল করো', array['micro']::text[], 'active', 110),
  ('pharmacology', 'Pharmacology', null, 'General pharmacology principles ahead of dental applications.', 'জেনারেল ফার্মাকোলজির বেসিক — ডেন্টাল ফার্মাকোলজিতে ঢোকার আগে।', (select id from public.phases where code = 2), (select id from public.media where path = 'flyers/pharmacology.jpg'), 'https://mediversebd.com/courses/pharmacology-full-course', 'Enroll on Mediverse', 'মেডিভার্সে এনরোল করো', array['drugs']::text[], 'active', 120),
  ('c-and-c-oral-patho-medicine-and-perio', 'C&C — Oral Patho, Medicine & Perio', null, 'Combined Oral Pathology, Oral Medicine and Periodontology.', 'Oral Pathology, Oral Medicine আর Periodontology — এক কোর্সেই।', (select id from public.phases where code = 3), (select id from public.media where path = 'flyers/cc-batch.jpg'), 'https://mediversebd.com/courses/cawson-carranza', 'Enroll on Mediverse', 'মেডিভার্সে এনরোল করো', array['cawson', 'carranza', 'oral', 'pathology', 'periodontology']::text[], 'active', 130),
  ('crash-course-on-peri-and-oral-patho', 'Crash Course on Peri & Oral Patho', null, 'Question-based rapid revision of Periodontology and Oral Pathology for written and viva.', 'প্রফের প্রশ্ন ধরে Periodontology আর Oral Pathology-র ঝটপট রিভিশন — লিখিত আর ভাইভা দুটোর জন্যই।', (select id from public.phases where code = 3), (select id from public.media where path = 'flyers/peri-oral-crash.jpg'), 'https://mediversebd.com/courses/crash-course-on-peri-oral-patho', 'Enroll on Mediverse', 'মেডিভার্সে এনরোল করো', array['cawson', 'carranza', 'perio', 'periodontology', 'oral', 'pathology', 'crash', 'revision']::text[], 'active', 140),
  ('essential-medicine-for-bds', 'Essential Medicine for BDS', null, 'Core general medicine concepts relevant to dental practice and exams.', 'ডেন্টাল প্র্যাকটিস আর পরীক্ষায় যতটুকু মেডিসিন লাগে, ঠিক ততটুকু।', (select id from public.phases where code = 3), (select id from public.media where path = 'flyers/medicine.jpg'), 'https://mediversebd.com/courses/essential-medicine-for-bds', 'Enroll on Mediverse', 'মেডিভার্সে এনরোল করো', array['general', 'medicine']::text[], 'active', 150),
  ('a-complete-solution-of-surgery', 'A Complete Solution of Surgery', null, 'Full prep for Surgery Paper I — written, viva, OSPE, long and short cases.', 'সার্জারি পেপার ওয়ানের পুরো প্রস্তুতি — লিখিত, ভাইভা, OSPE, লং কেস আর শর্ট কেস।', (select id from public.phases where code = 3), (select id from public.media where path = 'flyers/surgery.jpg'), 'https://mediversebd.com/courses/a-complete-solution-of-surgery', 'Enroll on Mediverse', 'মেডিভার্সে এনরোল করো', array['general', 'surgery', 'ospe', 'long', 'case', 'short', 'case']::text[], 'active', 160),
  ('mastering-maxillofacial-surgery', 'Mastering Maxillofacial Surgery', null, 'OMS concepts through to exam-format short and long cases.', 'OMS-এর কনসেপ্ট থেকে শুরু করে পরীক্ষার মতো করে শর্ট আর লং কেস।', (select id from public.phases where code = 4), (select id from public.media where path = 'flyers/oms.jpg'), 'https://mediversebd.com/courses/maxillofacial-surgery', 'Enroll on Mediverse', 'মেডিভার্সে এনরোল করো', array['oms', 'oral', 'surgery']::text[], 'active', 170),
